///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = async function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        const frm = (document.SearchForm || { elements: [] });
        if ((String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "DeclPopupYn" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("DeclPopupYn"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "DeclPopupYn" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("DeclPopupYn")))).indexOf('$' + '{') >= 0 ? '' : String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "DeclPopupYn" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("DeclPopupYn"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "DeclPopupYn" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("DeclPopupYn"))))) === 'Y') {
            const _width = '900';
            const _height = '350';
            const _left = Math.ceil((screen.width - _width) / 2);
            const _top = Math.ceil((screen.height - _height) / 2);
            let _previewWindow;
            _previewWindow = $c.win.openPopup('', { id: "_frnTodayDeclYn_popup", scrollbars: false, resizable: false, type: "pageFramePopup" }, {});
            $c.util.getComponent('dma_searchListReq').set('method', 'popupFrnTodayDeclYnView');
            frm.action = '/event/event.do';
            frm.target = '_frnTodayDeclYn_popup';
            /* 수동 전환 필요: SearchForm.submit() — as-is 자기제출(action 없음), 대체 tx 미정 */ await $c.win.alert("이 동작은 아직 전환되지 않았습니다(as-is 폼 «SearchForm» 자기제출 — 대체 서버 호출 미정).");
        }
        if ("" + dma_companyInfoVO.get("isurCd") + "" === "99996") {
            await scwin.searchFileList();
        } else {
            await scwin.searchList();
        }
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf05201.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldbnf05201.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////



///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_searchList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_searchList = async function () {
    const sbmOptions = {
        id: "tx_fn_searchList",
        method: "post",
        action: "/listeach/listeach.do",
        ref: "dma_searchListReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldbnf05201.tx_fn_searchList" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_searchFileList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_searchFileList = async function () {
    const sbmOptions = {
        id: "tx_fn_searchFileList",
        method: "post",
        action: "/upload/uploadFile.do",
        ref: "dma_searchFileListReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldbnf05201.tx_fn_searchFileList" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.searchList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.searchList = async function () {
    /* sdd-asis-lifecycle:begin fn_searchList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.SearchForm || { elements: [] });
    $c.util.getComponent('dma_searchListReq').set('method', "searchNonListingBondList");
    frm.action = '/listeach/listeach.do';
    frm.target = "_self";
    await scwin.tx_fn_searchList();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.searchFileList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.searchFileList = async function () {
    /* sdd-asis-lifecycle:begin fn_searchFileList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.SearchForm || { elements: [] });
    $c.util.getComponent('dma_searchListReq').set('method', "uploadForm");
    frm.action = '/upload/uploadFile.do';
    frm.target = "_self";
    await scwin.tx_fn_searchFileList();
    /* sdd-asis-lifecycle:end */
};
